  function createBasemapTileLayer(id) {
    const style = BASEMAP_STYLES[id];
    const attribution = `Base map and data from <a href="${COPYRIGHT_URL}" target="_blank" rel="noopener">OpenGeofiction and its contributors</a>${style.credit || ""}`;
    if (style.kind === "vector") {
      if (typeof window.L.maplibreGL !== "function") throw new Error("MapLibre layer is unavailable");
      const layer = window.L.maplibreGL({
        style: style.url,
        interactive: false,
        maxPitch: VECTOR_MAX_PITCH,
        pane: "tilePane",
        padding: 0.1,
        attributionControl: { customAttribution: attribution },
      });
      let ready = false;
      let timeout = null;
      let vectorMap = null;
      let onStyleImageMissing = null;
      layer.on("add", () => {
        const glMap = layer.getMaplibreMap();
        vectorMap = glMap;
        if (isHuayuBasemapId(id)) {
          onStyleImageMissing = (event) => addHuayuPoiImage(glMap, event.id);
          glMap.on("styleimagemissing", onStyleImageMissing);
        }
        timeout = window.setTimeout(() => {
          if (!ready && selectedBasemapId === id) {
            showToast("Vector 加载超时，已切回 OGF-Carto US");
            setBasemapStyle("carto");
          }
        }, 15000);
        glMap.once("load", () => {
          ready = true;
          if (timeout) window.clearTimeout(timeout);
          if (isHuayuBasemapId(id)) {
            ensureHuayuPoiImages(glMap);
            activateHuayuLiveBasemap(glMap);
            activateHuayuAdministrativeLabels(glMap);
            activateHuayuCityWalls(glMap);
            activateHuayuWalls(glMap);
            activateHuayuLiveBuildings(glMap);
            activateHuayuElevatedGreen(glMap);
            activateHuayuSupplementalPois(glMap);
          }
        });
      });
      layer.on("remove", () => {
        if (timeout) window.clearTimeout(timeout);
        if (isHuayuBasemapId(id)) {
          if (onStyleImageMissing) vectorMap?.off("styleimagemissing", onStyleImageMissing);
          [deactivateHuayuLiveBasemap, deactivateHuayuAdministrativeLabels,
            deactivateHuayuCityWalls, deactivateHuayuWalls, deactivateHuayuElevatedGreen,
            deactivateHuayuLiveBuildings, deactivateHuayuSupplementalPois].forEach((deactivate) => {
            try { deactivate(vectorMap); } catch {}
          });
        }
        onStyleImageMissing = null;
        vectorMap = null;
      });
      return layer;
    }
    const layer = window.L.tileLayer(style.url, {
      minZoom: 0,
      maxZoom: 19,
      maxNativeZoom: 19,
      updateWhenIdle: true,
      updateWhenZooming: false,
      keepBuffer: 2,
      reuseTiles: true,
      attribution,
      crossOrigin: true,
    });
    let warned = false;
    installBasemapTileFallback(layer, "auto", style.fallbackUrl || TILE_FALLBACK_URL,
      style.timeout || 8000, () => {
        if (id !== "carto" && selectedBasemapId === id && !warned) {
          warned = true;
          showToast(`${style.label} 部分瓦片不可用，已使用 OGF-Carto 补位`);
        }
      });
    return layer;
  }

  function ensureVectorBasemapLibrary() {
    if (typeof window.L.maplibreGL === "function") return Promise.resolve();
    if (vectorBasemapLibraryPromise) return vectorBasemapLibraryPromise;
    const loadStylesheet = () => new Promise((resolve, reject) => {
      const existing = document.getElementById("maplibre-stylesheet");
      if (existing) {
        if (existing.dataset.loaded === "true") resolve();
        else {
          existing.addEventListener("load", resolve, { once: true });
          existing.addEventListener("error", reject, { once: true });
        }
        return;
      }
      const link = document.createElement("link");
      link.id = "maplibre-stylesheet";
      link.rel = "stylesheet";
      link.href = "./maplibre-gl.css?v=5.24.0";
      link.addEventListener("load", () => {
        link.dataset.loaded = "true";
        resolve();
      }, { once: true });
      link.addEventListener("error", (error) => {
        link.remove();
        reject(error);
      }, { once: true });
      document.head.append(link);
    });
    const loadScript = (src, ready) => {
      if (ready()) return Promise.resolve();
      return new Promise((resolve, reject) => {
        const script = document.createElement("script");
        script.src = src;
        script.async = false;
        script.addEventListener("load", resolve, { once: true });
        script.addEventListener("error", (error) => {
          script.remove();
          reject(error);
        }, { once: true });
        document.head.append(script);
      });
    };
    vectorBasemapLibraryPromise = Promise.all([
      loadStylesheet(),
      loadScript("./maplibre-gl.js?v=5.24.0", () => Boolean(window.maplibregl)),
    ]).then(() => loadScript("./leaflet-maplibre-gl.js?v=0.1.4", () => typeof window.L.maplibreGL === "function"));
    vectorBasemapLibraryPromise.catch(() => { vectorBasemapLibraryPromise = null; });
    return vectorBasemapLibraryPromise;
  }

