  // The numbered OGF tile nodes occasionally accept a connection without
  // returning bytes or an error. Retry a genuinely stalled image against the
  // second official node, while keeping normal loads to one request per tile.
  function installBasemapTileFallback(layer, fetchPriority, fallbackUrl = TILE_FALLBACK_URL,
    timeoutMs = BASEMAP_TILE_TIMEOUT_MS, onFallback = null) {
    const timeoutByTile = new WeakMap();
    const clearTimeoutForTile = (tile) => {
      const timeout = timeoutByTile.get(tile);
      if (timeout) window.clearTimeout(timeout);
      timeoutByTile.delete(tile);
    };
    const fallback = (event) => {
      const tile = event.tile;
      if (!tile || tile.dataset.ogfFallback) return;
      clearTimeoutForTile(tile);
      tile.dataset.ogfFallback = "1";
      onFallback?.();
      tile.src = fallbackUrl
        .replace("{z}", String(event.coords.z))
        .replace("{x}", String(event.coords.x))
        .replace("{y}", String(event.coords.y));
    };
    layer.on("tileloadstart", (event) => {
      const tile = event.tile;
      if (!tile) return;
      tile.fetchPriority = fetchPriority;
      clearTimeoutForTile(tile);
      delete tile.dataset.ogfFallback;
      timeoutByTile.set(tile, window.setTimeout(() => fallback(event), timeoutMs));
    });
    layer.on("tileload", (event) => clearTimeoutForTile(event.tile));
    layer.on("tileunload", (event) => clearTimeoutForTile(event.tile));
    layer.on("tileerror", (event) => {
      if (event.tile?.dataset.ogfFallback) clearTimeoutForTile(event.tile);
      else fallback(event);
    });
  }

